//! Emits the *core-side* glue for a Go core (one file, `package main`):
//! plain Go types and their payload codec, one interface per resource that the
//! core implements, typed stubs for WIT imports (host calls, ABI 1.1), the
//! method-id dispatcher, and the `//export` wrappers under the package symbol
//! prefix. Everything contract-agnostic lives in the hand-written runtime
//! `runtime/go` (module `wabi.example/wabiabi`).
//!
//! The core provides, next to the generated file:
//!   const coreInfo = "..."                         (<prefix>_core_info)
//!   func new<Resource>(<ctor params>) <Resource>   (one per resource constructor)

use crate::abi_table::{symbol, CTy, FUNCTIONS};
use crate::ir::*;
use crate::names::*;
use anyhow::{bail, Result};

pub fn emit(m: &Model, abi_rel: &str) -> Result<String> {
    for r in &m.resources {
        if r.ctor.is_none() {
            bail!("target go: resource `{}` needs a constructor (resource handles as values are not supported yet)", r.name);
        }
    }
    let mut o = String::new();
    w!(o, "// Code generated by wabi-wit-gen from wit/*.wit. DO NOT EDIT.");
    w!(o, "");
    w!(o, "// Go core glue for {} (symbol prefix {}_).", m.contract_id(), m.symbol_prefix());
    w!(o, "// The core provides `const coreInfo` and `func new<Resource>(...)`; see the");
    w!(o, "// resource interfaces below.");
    w!(o, "");
    w!(o, "package main");
    w!(o, "");
    w!(o, "/*");
    w!(o, "#cgo CFLAGS: -I${{SRCDIR}}/{abi_rel}");
    w!(o, "#include \"wabi_abi.h\" // types only; cgo generates the prototypes of the //export functions");
    w!(o, "*/");
    w!(o, "import \"C\"");
    w!(o, "");
    w!(o, "import (");
    w!(o, "\t\"context\"");
    w!(o, "\t\"fmt\"");
    w!(o, "\t\"math\"");
    w!(o, "\t\"unsafe\"");
    w!(o, "");
    w!(o, "\twabiabi \"wabi.example/wabiabi\"");
    w!(o, ")");
    w!(o, "");
    w!(o, "var (");
    w!(o, "\t_ context.Context");
    w!(o, "\t_ = fmt.Sprint");
    w!(o, "\t_ = math.MaxUint8");
    w!(o, ")");
    w!(o, "");
    w!(o, "// ContractID is the WIT package this core implements.");
    w!(o, "const ContractID = \"{}\"", m.contract_id());
    w!(o, "");
    w!(o, "// Resource groups and stable method ids, pinned in wit/abi-ids.lock.");
    w!(o, "const (");
    let mut b = Block::default();
    for r in &m.resources {
        b.row(format!("group{}", pascal(&r.name)), format!("uint32 = {:#04x}", r.group));
        for f in r.ctor.iter().chain(&r.methods) {
            b.row(mid(&r.name, &f.name), format!("uint32 = {:#06x}", f.id));
        }
    }
    for h in &m.imports {
        b.comment(&Some(format!("import `{}`: implemented by the app, called by the core", h.name)));
        b.row(format!("group{}", pascal(&h.name)), format!("uint32 = {:#04x}", h.group));
        for f in &h.funcs {
            b.row(mid(&h.name, &f.name), format!("uint32 = {:#06x}", f.id));
        }
    }
    b.render(&mut o, "\t");
    w!(o, ")");
    w!(o, "");

    for t in &m.types {
        emit_type(&mut o, t);
    }
    for r in &m.resources {
        emit_interface(&mut o, r);
    }
    for h in &m.imports {
        emit_import(&mut o, h);
    }
    emit_dispatch(&mut o, m);
    emit_exports(&mut o, m);
    Ok(o)
}

/// A `const (...)` or struct body: gofmt aligns the second column of
/// consecutive `name rest` lines; comment lines end such a run.
#[derive(Default)]
struct Block(Vec<(String, Option<String>)>);

impl Block {
    fn comment(&mut self, d: &Option<String>) {
        if let Some(d) = d {
            for l in d.lines() {
                self.0.push((format!("// {}", l.trim_end()), None));
            }
        }
    }
    fn row(&mut self, name: impl Into<String>, rest: impl Into<String>) {
        self.0.push((name.into(), Some(rest.into())));
    }
    fn render(&self, o: &mut String, indent: &str) {
        let mut i = 0;
        while i < self.0.len() {
            let mut j = i;
            while j < self.0.len() && self.0[j].1.is_some() {
                j += 1;
            }
            let width = self.0[i..j].iter().map(|(n, _)| n.len()).max().unwrap_or(0);
            for (n, rest) in &self.0[i..j] {
                w!(o, "{indent}{n:width$} {}", rest.as_ref().unwrap());
            }
            if j < self.0.len() {
                w!(o, "{indent}{}", self.0[j].0);
                j += 1;
            }
            i = j;
        }
    }
}

fn mid(owner: &str, func: &str) -> String {
    format!("method{}{}", pascal(owner), pascal(func))
}

const GO_RESERVED: &[&str] = &[
    "break", "case", "chan", "const", "continue", "default", "defer", "else", "fallthrough", "for", "func", "go",
    "goto", "if", "import", "interface", "map", "package", "range", "return", "select", "struct", "switch", "type",
    "var", "w", "r", "ctx", "this", "ok", "e", "ret", "object", "method", "req", "resp", "err", "v", "n",
];

/// Local identifier for a WIT parameter.
fn local(n: &str) -> String {
    let c = camel(n);
    if GO_RESERVED.contains(&c.as_str()) {
        format!("{c}_")
    } else {
        c
    }
}

fn docs(o: &mut String, d: &Option<String>, indent: &str) {
    if let Some(d) = d {
        for l in d.lines() {
            w!(o, "{indent}// {}", l.trim_end());
        }
    }
}

fn gty(t: &Ty) -> String {
    match t {
        Ty::Bool => "bool".into(),
        Ty::U8 => "uint8".into(),
        Ty::U16 => "uint16".into(),
        Ty::U32 => "uint32".into(),
        Ty::U64 => "uint64".into(),
        Ty::S8 => "int8".into(),
        Ty::S16 => "int16".into(),
        Ty::S32 => "int32".into(),
        Ty::S64 => "int64".into(),
        Ty::F32 => "float32".into(),
        Ty::F64 => "float64".into(),
        Ty::Char => "rune".into(),
        Ty::String => "string".into(),
        Ty::Bytes => "[]byte".into(),
        Ty::List(t) => format!("[]{}", gty(t)),
        Ty::Option(t) => format!("*{}", gty(t)),
        Ty::Tuple(ts) => format!(
            "struct{{ {} }}",
            ts.iter().enumerate().map(|(i, t)| format!("F{i} {}", gty(t))).collect::<Vec<_>>().join("; ")
        ),
        Ty::Named(n) => pascal(n),
        Ty::Stream(t) => format!("wabiabi.Stream[{}]", gty(t)),
        Ty::Handle { resource, .. } => pascal(resource), // the core's interface of that resource
    }
}

/// Go result list of a core-implemented method.
fn ret_sig(r: &Ret) -> String {
    match r {
        Ret::Unit => String::new(),
        Ret::Value(t) => format!(" {}", gty(t)),
        Ret::Result { ok: None, err } => format!(" *{}", err_ty(err)),
        Ret::Result { ok: Some(t), err } => format!(" ({}, *{})", gty(t), err_ty(err)),
    }
}

fn err_ty(e: &Option<Ty>) -> String {
    e.as_ref().map(gty).unwrap_or_else(|| "struct{}".into())
}

/// `e` of the form `*x` must be parenthesised before selecting a field.
fn sel(e: &str, f: &str) -> String {
    if e.starts_with('*') {
        format!("({e}).{f}")
    } else {
        format!("{e}.{f}")
    }
}

/// Statements (one per line, relative indentation) encoding value expression `e`.
fn enc(t: &Ty, e: &str, d: usize) -> Vec<String> {
    let x = format!("x{d}");
    match t {
        Ty::Bool => vec![format!("w.Bool({e})")],
        Ty::U8 | Ty::U16 | Ty::U32 | Ty::U64 | Ty::Char => vec![format!("w.Uint(uint64({e}))")],
        Ty::S8 | Ty::S16 | Ty::S32 | Ty::S64 => vec![format!("w.Int(int64({e}))")],
        Ty::F32 => vec![format!("w.F32({e})")],
        Ty::F64 => vec![format!("w.F64({e})")],
        Ty::String => vec![format!("w.Str({e})")],
        Ty::Bytes => vec![format!("w.Bin({e})")],
        Ty::List(t) => {
            let mut v = vec![format!("w.Array(len({e}))"), format!("for _, {x} := range {e} {{")];
            v.extend(enc(t, &x, d + 1).into_iter().map(|l| format!("\t{l}")));
            v.push("}".into());
            v
        }
        Ty::Option(t) => {
            let mut v = vec![format!("if {x} := {e}; {x} != nil {{")];
            v.extend(enc(t, &format!("*{x}"), d + 1).into_iter().map(|l| format!("\t{l}")));
            v.push("} else {".into());
            v.push("\tw.Nil()".into());
            v.push("}".into());
            v
        }
        Ty::Tuple(ts) => {
            let mut v = vec![format!("w.Array({})", ts.len())];
            for (i, t) in ts.iter().enumerate() {
                v.extend(enc(t, &sel(e, &format!("F{i}")), d + 1));
            }
            v
        }
        Ty::Named(n) => vec![format!("encode{}(w, {e})", pascal(n))],
        Ty::Stream(_) => unreachable!("streams are encoded by the dispatcher"),
        // a resource the core hands to the host: it gets its own handle
        Ty::Handle { resource, .. } => vec![format!("w.Uint(wabiabi.NewObject(group{}, {e}))", pascal(resource))],
    }
}

/// Expression decoding a value of type `t` from reader `r` (sticky errors).
fn dec(t: &Ty) -> String {
    match t {
        Ty::Bool => "r.Bool()".into(),
        Ty::U8 => "uint8(r.Uint(math.MaxUint8))".into(),
        Ty::U16 => "uint16(r.Uint(math.MaxUint16))".into(),
        Ty::U32 => "uint32(r.Uint(math.MaxUint32))".into(),
        Ty::U64 => "r.Uint(math.MaxUint64)".into(),
        Ty::S8 => "int8(r.Int(math.MinInt8, math.MaxInt8))".into(),
        Ty::S16 => "int16(r.Int(math.MinInt16, math.MaxInt16))".into(),
        Ty::S32 => "int32(r.Int(math.MinInt32, math.MaxInt32))".into(),
        Ty::S64 => "r.Int(math.MinInt64, math.MaxInt64)".into(),
        Ty::F32 => "r.F32()".into(),
        Ty::F64 => "r.F64()".into(),
        Ty::Char => "r.Char()".into(),
        Ty::String => "r.Str()".into(),
        Ty::Bytes => "r.Bin()".into(),
        Ty::List(i) => format!("wabiabi.ReadList(r, func(r *wabiabi.Reader) {} {{ return {} }})", gty(i), dec(i)),
        Ty::Option(i) => format!("wabiabi.ReadOpt(r, func(r *wabiabi.Reader) {} {{ return {} }})", gty(i), dec(i)),
        Ty::Tuple(ts) => {
            let mut s = format!("func(r *wabiabi.Reader) (t {}) {{ if r.Array() != {} {{ r.Fail(\"tuple arity\") }}; ", gty(t), ts.len());
            for (i, ti) in ts.iter().enumerate() {
                s += &format!("t.F{i} = {}; ", dec(ti));
            }
            s + "return }(r)"
        }
        Ty::Named(n) => format!("decode{}(r)", pascal(n)),
        Ty::Stream(_) => unreachable!(),
        // a borrowed object stays, an owned one moves into the core
        Ty::Handle { resource, owned } => format!("wabiabi.HandleArg[{0}](r, group{0}, {owned})", pascal(resource)),
    }
}

fn push(o: &mut String, indent: &str, lines: Vec<String>) {
    for l in lines {
        w!(o, "{indent}{l}");
    }
}

fn emit_type(o: &mut String, t: &TypeDecl) {
    let name = pascal(&t.name);
    docs(o, &t.docs, "");
    match &t.kind {
        TypeKind::Record(fields) => {
            w!(o, "type {name} struct {{");
            let mut b = Block::default();
            for f in fields {
                b.comment(&f.docs);
                b.row(pascal(&f.name), gty(&f.ty));
            }
            b.render(o, "\t");
            w!(o, "}}");
            w!(o, "");
            w!(o, "func encode{name}(w *wabiabi.Writer, v {name}) {{");
            let required = fields.iter().filter(|f| !matches!(f.ty, Ty::Option(_))).count();
            w!(o, "\tn := {required}");
            for f in fields.iter().filter(|f| matches!(f.ty, Ty::Option(_))) {
                w!(o, "\tif v.{} != nil {{", pascal(&f.name));
                w!(o, "\t\tn++");
                w!(o, "\t}}");
            }
            w!(o, "\tw.Map(n)");
            for f in fields {
                let fname = pascal(&f.name);
                if let Ty::Option(inner) = &f.ty {
                    w!(o, "\tif v.{fname} != nil {{");
                    w!(o, "\t\tw.Uint({})", f.tag);
                    push(o, "\t\t", enc(inner, &format!("*v.{fname}"), 1));
                    w!(o, "\t}}");
                } else {
                    w!(o, "\tw.Uint({})", f.tag);
                    push(o, "\t", enc(&f.ty, &format!("v.{fname}"), 1));
                }
            }
            w!(o, "}}");
            w!(o, "");
            w!(o, "func decode{name}(r *wabiabi.Reader) (v {name}) {{");
            w!(o, "\tn := r.Map()");
            let req: Vec<&Field> = fields.iter().filter(|f| !matches!(f.ty, Ty::Option(_))).collect();
            for f in &req {
                w!(o, "\thas{} := false", pascal(&f.name));
            }
            w!(o, "\tfor i := 0; r.Err == nil && i < n; i++ {{");
            w!(o, "\t\tswitch r.Uint(math.MaxUint32) {{");
            for f in fields {
                w!(o, "\t\tcase {}:", f.tag);
                w!(o, "\t\t\tv.{} = {}", pascal(&f.name), dec(&f.ty));
                if !matches!(f.ty, Ty::Option(_)) {
                    w!(o, "\t\t\thas{} = true", pascal(&f.name));
                }
            }
            w!(o, "\t\tdefault:");
            w!(o, "\t\t\tr.Skip() // field of a newer peer");
            w!(o, "\t\t}}");
            w!(o, "\t}}");
            for f in &req {
                w!(o, "\tif !has{} {{", pascal(&f.name));
                w!(o, "\t\tr.Missing(\"{}.{}\")", t.name, f.name);
                w!(o, "\t}}");
            }
            w!(o, "\treturn");
            w!(o, "}}");
        }
        TypeKind::Variant(cases) => {
            w!(o, "type {name}Tag uint32");
            w!(o, "");
            w!(o, "const (");
            let mut b = Block::default();
            for c in cases {
                b.comment(&c.docs);
                b.row(format!("{name}{}", pascal(&c.name)), format!("{name}Tag = {}", c.tag));
            }
            b.render(o, "\t");
            w!(o, ")");
            w!(o, "");
            w!(o, "func (t {name}Tag) String() string {{");
            w!(o, "\tswitch t {{");
            for c in cases {
                w!(o, "\tcase {name}{}:", pascal(&c.name));
                w!(o, "\t\treturn \"{}\"", c.name);
            }
            w!(o, "\t}}");
            w!(o, "\treturn fmt.Sprintf(\"{}(%d)\", uint32(t))", t.name);
            w!(o, "}}");
            w!(o, "");
            w!(o, "// {name}: Tag selects the case; the field named like the case holds its payload.");
            w!(o, "type {name} struct {{");
            let mut b = Block::default();
            b.row("Tag", format!("{name}Tag"));
            for c in cases {
                if let Some(ty) = &c.ty {
                    b.row(pascal(&c.name), gty(ty));
                }
            }
            b.render(o, "\t");
            w!(o, "}}");
            w!(o, "");
            w!(o, "func encode{name}(w *wabiabi.Writer, v {name}) {{");
            w!(o, "\tswitch v.Tag {{");
            for c in cases {
                if let Some(ty) = &c.ty {
                    w!(o, "\tcase {name}{}:", pascal(&c.name));
                    w!(o, "\t\tw.Array(2)");
                    w!(o, "\t\tw.Uint({})", c.tag);
                    push(o, "\t\t", enc(ty, &format!("v.{}", pascal(&c.name)), 1));
                }
            }
            w!(o, "\tdefault:");
            w!(o, "\t\tw.Array(1)");
            w!(o, "\t\tw.Uint(uint64(v.Tag))");
            w!(o, "\t}}");
            w!(o, "}}");
            w!(o, "");
            w!(o, "func decode{name}(r *wabiabi.Reader) (v {name}) {{");
            w!(o, "\tn := r.Array()");
            w!(o, "\tif r.Err == nil && n == 0 {{");
            w!(o, "\t\tr.Fail(\"{}: empty variant\")", t.name);
            w!(o, "\t}}");
            w!(o, "\tused := 1");
            w!(o, "\tv.Tag = {name}Tag(r.Uint(math.MaxUint32))");
            w!(o, "\tswitch {{");
            w!(o, "\tcase r.Err != nil:");
            let unit: Vec<String> = cases.iter().filter(|c| c.ty.is_none()).map(|c| format!("{name}{}", pascal(&c.name))).collect();
            if !unit.is_empty() {
                w!(o, "\tcase {}:", unit.iter().map(|c| format!("v.Tag == {c}")).collect::<Vec<_>>().join(" || "));
            }
            for c in cases {
                if let Some(ty) = &c.ty {
                    w!(o, "\tcase v.Tag == {name}{} && n >= 2:", pascal(&c.name));
                    w!(o, "\t\tv.{} = {}", pascal(&c.name), dec(ty));
                    w!(o, "\t\tused = 2");
                }
            }
            w!(o, "\tdefault:");
            w!(o, "\t\tr.Fail(\"{}: unknown case %d\", uint32(v.Tag))", t.name);
            w!(o, "\t}}");
            w!(o, "\tfor ; r.Err == nil && used < n; used++ {{");
            w!(o, "\t\tr.Skip()");
            w!(o, "\t}}");
            w!(o, "\treturn");
            w!(o, "}}");
        }
        TypeKind::Enum(cases) => {
            w!(o, "type {name} uint32");
            w!(o, "");
            w!(o, "const (");
            let mut b = Block::default();
            for c in cases {
                b.comment(&c.docs);
                b.row(format!("{name}{}", pascal(&c.name)), format!("{name} = {}", c.tag));
            }
            b.render(o, "\t");
            w!(o, ")");
            w!(o, "");
            w!(o, "func encode{name}(w *wabiabi.Writer, v {name}) {{ w.Uint(uint64(v)) }}");
            w!(o, "");
            w!(o, "func decode{name}(r *wabiabi.Reader) {name} {{");
            w!(o, "\tv := {name}(r.Uint(math.MaxUint32))");
            w!(o, "\tswitch v {{");
            w!(o, "\tcase {}:", cases.iter().map(|c| format!("{name}{}", pascal(&c.name))).collect::<Vec<_>>().join(", "));
            w!(o, "\tdefault:");
            w!(o, "\t\tr.Fail(\"{}: unknown case %d\", uint32(v))", t.name);
            w!(o, "\t}}");
            w!(o, "\treturn v");
            w!(o, "}}");
        }
    }
    if t.is_error {
        w!(o, "");
        w!(o, "func (e *{name}) Error() string {{ return fmt.Sprintf(\"{}: %+v\", *e) }}", t.name);
    }
    w!(o, "");
}

fn params_sig(f: &Func) -> Vec<String> {
    f.params.iter().map(|(n, t)| format!("{} {}", local(n), gty(t))).collect()
}

fn emit_interface(o: &mut String, r: &Resource) {
    let name = pascal(&r.name);
    docs(o, &r.docs, "");
    w!(o, "//");
    w!(o, "// Implemented by the core. Async methods get a ctx that is cancelled when");
    w!(o, "// the host cancels or drops the future. Close runs when the host drops the");
    w!(o, "// handle; calls still in flight may keep using the object.");
    if let Some(c) = &r.ctor {
        w!(o, "// The core provides the constructor: func new{name}({}) {name}", params_sig(c).join(", "));
    }
    w!(o, "type {name} interface {{");
    for f in &r.methods {
        docs(o, &f.docs, "\t");
        let mut ps = params_sig(f);
        if f.is_async {
            ps.insert(0, "ctx context.Context".into());
        }
        w!(o, "\t{}({}){}", pascal(&f.name), ps.join(", "), ret_sig(&f.ret));
    }
    w!(o, "\tClose()");
    w!(o, "}}");
    w!(o, "");
}

/// Encodes `ret` (a value of the method's result) into `w`.
fn encode_ret(o: &mut String, ret: &Ret, call: &str, indent: &str) {
    match ret {
        Ret::Unit => {
            w!(o, "{indent}{call}");
            w!(o, "{indent}w.Nil()");
        }
        Ret::Value(Ty::Stream(item)) => {
            w!(o, "{indent}s := {call}");
            w!(o, "{indent}w.Uint(wabiabi.NewStream(s, func(w *wabiabi.Writer, x0 {}) {{", gty(item));
            push(o, &format!("{indent}\t"), enc(item, "x0", 1));
            w!(o, "{indent}}}))");
        }
        Ret::Value(t) => {
            w!(o, "{indent}ret := {call}");
            push(o, indent, enc(t, "ret", 1));
        }
        Ret::Result { ok, err } => {
            if ok.is_some() {
                w!(o, "{indent}ret, e := {call}");
            } else {
                w!(o, "{indent}e := {call}");
            }
            w!(o, "{indent}w.Array(2)");
            w!(o, "{indent}if e != nil {{");
            w!(o, "{indent}\tw.Uint(1)");
            match err {
                Some(t) => push(o, &format!("{indent}\t"), enc(t, "*e", 1)),
                None => w!(o, "{indent}\tw.Nil()"),
            }
            w!(o, "{indent}}} else {{");
            w!(o, "{indent}\tw.Uint(0)");
            match ok {
                Some(t) => push(o, &format!("{indent}\t"), enc(t, "ret", 1)),
                None => w!(o, "{indent}\tw.Nil()"),
            }
            w!(o, "{indent}}}");
        }
    }
}

fn decode_params(o: &mut String, f: &Func, indent: &str) {
    w!(o, "{indent}r := wabiabi.NewReader(req)");
    w!(o, "{indent}r.Params({})", f.params.len());
    for (n, t) in &f.params {
        w!(o, "{indent}{} := {}", local(n), dec(t));
    }
    w!(o, "{indent}r.Finish()");
}

fn args(f: &Func) -> String {
    f.params.iter().map(|(n, _)| local(n)).collect::<Vec<_>>().join(", ")
}

fn emit_dispatch(o: &mut String, m: &Model) {
    w!(o, "// dispatcher maps method ids to the core (wabiabi.Dispatcher).");
    w!(o, "type dispatcher struct{{}}");
    w!(o, "");
    w!(o, "func (dispatcher) DispatchSync(object uint64, method uint32, req []byte) ([]byte, int32) {{");
    w!(o, "\tw := &wabiabi.Writer{{}}");
    w!(o, "\tswitch method {{");
    for r in &m.resources {
        let rn = pascal(&r.name);
        let c = r.ctor.as_ref().unwrap();
        w!(o, "\tcase {}:", mid(&r.name, &c.name));
        w!(o, "\t\tif object != 0 {{");
        w!(o, "\t\t\treturn nil, wabiabi.ErrInvalidHandle");
        w!(o, "\t\t}}");
        decode_params(o, c, "\t\t");
        w!(o, "\t\tif r.Err != nil {{");
        w!(o, "\t\t\treturn []byte(r.Err.Error()), r.Status()");
        w!(o, "\t\t}}");
        w!(o, "\t\tw.Uint(wabiabi.NewObject(group{rn}, new{rn}({})))", args(c));
        for f in r.methods.iter().filter(|f| !f.is_async) {
            w!(o, "\tcase {}:", mid(&r.name, &f.name));
            w!(o, "\t\tthis, ok := wabiabi.Object[{rn}](object)");
            w!(o, "\t\tif !ok {{");
            w!(o, "\t\t\treturn nil, wabiabi.ErrInvalidHandle");
            w!(o, "\t\t}}");
            decode_params(o, f, "\t\t");
            w!(o, "\t\tif r.Err != nil {{");
            w!(o, "\t\t\treturn []byte(r.Err.Error()), r.Status()");
            w!(o, "\t\t}}");
            encode_ret(o, &f.ret, &format!("this.{}({})", pascal(&f.name), args(f)), "\t\t");
        }
        let asyncs: Vec<String> = r.methods.iter().filter(|f| f.is_async).map(|f| mid(&r.name, &f.name)).collect();
        if !asyncs.is_empty() {
            w!(o, "\tcase {}:", asyncs.join(", "));
            w!(o, "\t\treturn nil, wabiabi.ErrUnsupported");
        }
    }
    w!(o, "\tdefault:");
    w!(o, "\t\treturn nil, wabiabi.ErrUnknownMethod");
    w!(o, "\t}}");
    w!(o, "\treturn w.B, wabiabi.OK");
    w!(o, "}}");
    w!(o, "");
    w!(o, "func (dispatcher) DispatchAsync(object uint64, method uint32, req []byte) (func(context.Context) []byte, int32) {{");
    w!(o, "\tswitch method {{");
    for r in &m.resources {
        let rn = pascal(&r.name);
        for f in r.methods.iter().filter(|f| f.is_async) {
            w!(o, "\tcase {}:", mid(&r.name, &f.name));
            w!(o, "\t\tthis, ok := wabiabi.Object[{rn}](object)");
            w!(o, "\t\tif !ok {{");
            w!(o, "\t\t\treturn nil, wabiabi.ErrInvalidHandle");
            w!(o, "\t\t}}");
            decode_params(o, f, "\t\t");
            w!(o, "\t\tif r.Err != nil {{");
            w!(o, "\t\t\treturn nil, r.Status()");
            w!(o, "\t\t}}");
            w!(o, "\t\treturn func(ctx context.Context) []byte {{");
            w!(o, "\t\t\tw := &wabiabi.Writer{{}}");
            let a = args(f);
            let call = format!("this.{}(ctx{}{a})", pascal(&f.name), if a.is_empty() { "" } else { ", " });
            encode_ret(o, &f.ret, &call, "\t\t\t");
            w!(o, "\t\t\treturn w.B");
            w!(o, "\t\t}}, wabiabi.OK");
        }
        let syncs: Vec<String> =
            r.ctor.iter().chain(r.methods.iter().filter(|f| !f.is_async)).map(|f| mid(&r.name, &f.name)).collect();
        w!(o, "\tcase {}:", syncs.join(", "));
        w!(o, "\t\treturn nil, wabiabi.ErrUnsupported");
    }
    w!(o, "\t}}");
    w!(o, "\treturn nil, wabiabi.ErrUnknownMethod");
    w!(o, "}}");
    w!(o, "");
}

/// Typed stubs for the functions of an imported interface: the core calls
/// them, the app implements them (host calls, ABI.md §4a).
fn emit_import(o: &mut String, h: &HostInterface) {
    w!(o, "// ---- import `{}`: implemented by the app, called by the core ----", h.name);
    docs(o, &h.docs, "");
    w!(o, "");
    for f in &h.funcs {
        let fname = format!("{}{}", pascal(&h.name), pascal(&f.name));
        let (rets, zero): (Vec<String>, Vec<&str>) = match &f.ret {
            Ret::Unit => (vec![], vec![]),
            Ret::Value(t) => (vec![gty(t)], vec!["ret"]),
            Ret::Result { ok: None, err } => (vec![format!("*{}", err_ty(err))], vec!["nil"]),
            Ret::Result { ok: Some(t), err } => (vec![gty(t), format!("*{}", err_ty(err))], vec!["ret", "nil"]),
        };
        let mut sig = rets.clone();
        sig.push("error".into());
        let fail = |err: &str| {
            let mut v: Vec<String> = zero.iter().map(|s| s.to_string()).collect();
            v.push(err.into());
            v.join(", ")
        };
        w!(o, "// {fname} runs `{}.{}` in the app. The last result is a transport", h.name, f.name);
        w!(o, "// error (*wabiabi.HostError): no handler, cancelled, or a malformed answer.");
        w!(o, "// Only call it from async work.");
        if f.docs.is_some() {
            w!(o, "//");
            docs(o, &f.docs, "");
        }
        let mut ps = vec!["ctx context.Context".to_string()];
        ps.extend(params_sig(f));
        let sig_s = if sig.len() == 1 { sig[0].clone() } else { format!("({})", sig.join(", ")) };
        w!(o, "func {fname}({}) {sig_s} {{", ps.join(", "));
        if let Ret::Value(t) | Ret::Result { ok: Some(t), .. } = &f.ret {
            w!(o, "\tvar ret {}", gty(t));
        }
        w!(o, "\tw := &wabiabi.Writer{{}}");
        w!(o, "\tw.Array({})", f.params.len());
        for (n, t) in &f.params {
            push(o, "\t", enc(t, &local(n), 1));
        }
        w!(o, "\tresp, err := wabiabi.HostCall(ctx, {}, w.B)", mid(&h.name, &f.name));
        w!(o, "\tif err != nil {{");
        w!(o, "\t\treturn {}", fail("err"));
        w!(o, "\t}}");
        w!(o, "\tr := wabiabi.NewReader(resp)");
        let mut outs: Vec<String> = vec![];
        match &f.ret {
            Ret::Unit => w!(o, "\tr.Skip()"),
            Ret::Value(t) => {
                w!(o, "\tret = {}", dec(t));
                outs.push("ret".into());
            }
            Ret::Result { ok, err } => {
                w!(o, "\tvar e *{}", err_ty(err));
                w!(o, "\tif n := r.Array(); r.Err == nil && n != 2 {{");
                w!(o, "\t\tr.Fail(\"result must be [tag, value]\")");
                w!(o, "\t}}");
                w!(o, "\tif r.Uint(1) == 0 {{");
                match ok {
                    Some(t) => w!(o, "\t\tret = {}", dec(t)),
                    None => w!(o, "\t\tr.Skip()"),
                }
                w!(o, "\t}} else {{");
                match err {
                    Some(t) => {
                        w!(o, "\t\tx := {}", dec(t));
                        w!(o, "\t\te = &x");
                    }
                    None => {
                        w!(o, "\t\tr.Skip()");
                        w!(o, "\t\te = &struct{{}}{{}}");
                    }
                }
                w!(o, "\t}}");
                if ok.is_some() {
                    outs.push("ret".into());
                }
                outs.push("e".into());
            }
        }
        w!(o, "\tr.Finish()");
        w!(o, "\tif r.Err != nil {{");
        w!(o, "\t\treturn {}", fail("&wabiabi.HostError{Status: wabiabi.ErrInvalidArgument, Message: r.Err.Error()}"));
        w!(o, "\t}}");
        outs.push("nil".into());
        w!(o, "\treturn {}", outs.join(", "));
        w!(o, "}}");
        w!(o, "");
    }
}

fn cgo(t: CTy) -> &'static str {
    match t {
        CTy::Void => "",
        CTy::U32 => "C.uint32_t",
        CTy::U64 | CTy::Handle => "C.uint64_t",
        CTy::Status => "C.wabi_status",
        CTy::Bytes => "C.wabi_bytes",
        CTy::Buffer => "C.wabi_buffer",
        CTy::BufferPtr => "*C.wabi_buffer",
        CTy::HandlePtr => "*C.uint64_t",
        CTy::Callback => "C.wabi_future_callback",
        CTy::VoidPtr => "unsafe.Pointer",
        CTy::CStr => "*C.char",
        CTy::HostHandler => "C.wabi_host_handler",
        CTy::HostHandler2 => "C.wabi_host_handler2",
        CTy::HostCancel => "C.wabi_host_cancel",
    }
}

/// Body of each `//export` wrapper: C types in, generic runtime call, C types out.
fn export_body(name: &str) -> &'static [&'static str] {
    match name {
        "wabi_abi_version" => &["return C.uint32_t(wabiabi.AbiVersion)"],
        "wabi_abi_capabilities" => &["return C.uint64_t(wabiabi.Capabilities(hostCalls))"],
        "wabi_contract_id" => &["return (*C.char)(contractIDC)"],
        "wabi_core_info" => &["return (*C.char)(coreInfoC)"],
        "wabi_status_name" => &["return (*C.char)(wabiabi.StatusName(int32(status)))"],
        "wabi_buffer_free" => &["wabiabi.Free(unsafe.Pointer(buffer.ptr))"],
        "wabi_call_sync" => &[
            "if outResponse == nil {",
            "\treturn C.wabi_status(wabiabi.ErrInvalidArgument)",
            "}",
            "p, n, st := wabiabi.CallSync(dispatcher{}, uint64(object), uint32(methodId), unsafe.Pointer(request.ptr), int(request.len))",
            "*outResponse = C.wabi_buffer{ptr: (*C.uint8_t)(p), len: C.size_t(n)}",
            "return C.wabi_status(st)",
        ],
        "wabi_call_async" => &[
            "if outFuture == nil {",
            "\treturn C.wabi_status(wabiabi.ErrInvalidArgument)",
            "}",
            "f, st := wabiabi.CallAsync(dispatcher{}, uint64(object), uint32(methodId), unsafe.Pointer(request.ptr), int(request.len))",
            "*outFuture = C.uint64_t(f)",
            "return C.wabi_status(st)",
        ],
        "wabi_object_drop" => &["return C.wabi_status(wabiabi.ObjectDrop(uint64(object)))"],
        "wabi_future_subscribe" => &[
            "return C.wabi_status(wabiabi.FutureSubscribe(uint64(future), unsafe.Pointer(callback), userData))",
        ],
        "wabi_future_poll" => &["return C.wabi_status(wabiabi.FuturePoll(uint64(future)))"],
        "wabi_future_take" => &[
            "if outResult == nil {",
            "\treturn C.wabi_status(wabiabi.ErrInvalidArgument)",
            "}",
            "p, n, st := wabiabi.FutureTake(uint64(future))",
            "*outResult = C.wabi_buffer{ptr: (*C.uint8_t)(p), len: C.size_t(n)}",
            "return C.wabi_status(st)",
        ],
        "wabi_future_cancel" => &["return C.wabi_status(wabiabi.FutureCancel(uint64(future)))"],
        "wabi_future_drop" => &["return C.wabi_status(wabiabi.FutureDrop(uint64(future)))"],
        "wabi_stream_next" => &[
            "if outFuture == nil {",
            "\treturn C.wabi_status(wabiabi.ErrInvalidArgument)",
            "}",
            "f, st := wabiabi.StreamNext(uint64(stream))",
            "*outFuture = C.uint64_t(f)",
            "return C.wabi_status(st)",
        ],
        "wabi_stream_cancel" => &["return C.wabi_status(wabiabi.StreamCancel(uint64(stream)))"],
        "wabi_stream_drop" => &["return C.wabi_status(wabiabi.StreamDrop(uint64(stream)))"],
        "wabi_host_register" => &["return C.wabi_status(wabiabi.HostRegister(unsafe.Pointer(handler), userData))"],
        "wabi_host_register2" => &[
            "return C.wabi_status(wabiabi.HostRegister2(unsafe.Pointer(handler), unsafe.Pointer(onCancel), userData))",
        ],
        "wabi_host_reply" => &[
            "return C.wabi_status(wabiabi.HostReply(uint64(call), int32(status), unsafe.Pointer(response.ptr), int(response.len)))",
        ],
        other => panic!("gen_go: no export body for {other}"),
    }
}

fn emit_exports(o: &mut String, m: &Model) {
    let prefix = m.symbol_prefix();
    w!(o, "// ---- exported ABI symbols (prefix {prefix}_, ABI.md §1.1) ----");
    w!(o, "");
    w!(o, "const hostCalls = {}", m.needs_host_calls());
    w!(o, "");
    w!(o, "var (");
    w!(o, "\tcontractIDC = wabiabi.CString(ContractID) // static for the process lifetime");
    w!(o, "\tcoreInfoC   = wabiabi.CString(coreInfo)");
    w!(o, ")");
    for f in FUNCTIONS.iter().filter(|f| !f.host_call || m.needs_host_calls()) {
        let sym = symbol(&prefix, f.name);
        let ps: Vec<String> = f.params.iter().map(|(t, n)| format!("{n} {}", cgo(*t))).collect();
        let ret = if f.ret == CTy::Void { String::new() } else { format!(" {}", cgo(f.ret)) };
        w!(o, "");
        w!(o, "//export {sym}");
        w!(o, "func {sym}({}){ret} {{", ps.join(", "));
        for l in export_body(f.name) {
            w!(o, "\t{l}");
        }
        w!(o, "}}");
    }
    w!(o, "");
    w!(o, "func main() {{}} // required by -buildmode=c-shared");
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_abi_function_has_an_export_body() {
        for f in crate::abi_table::FUNCTIONS {
            assert!(!super::export_body(f.name).is_empty());
        }
    }
}

/// Editable implementation skeleton beside the generated Go glue.
pub fn scaffold(m: &Model) -> String {
    let mut o = String::from("// Starter implementation: edit freely; never overwritten by the generator.\npackage main\nimport (\n\"context\"\nwabiabi \"wabi.example/wabiabi\"\n)\nvar _ context.Context\nvar _ = wabiabi.OK\nfunc main() {}\n");
    w!(o, "const coreInfo = \"{} starter (unimplemented)\"", m.contract_id());
    for r in &m.resources {
        let name = pascal(&r.name);
        w!(o, "type starter{name} struct {{}}");
        w!(o, "func new{name}({}) {name} {{ return &starter{name}{{}} }}", params_sig(r.ctor.as_ref().unwrap()).join(", "));
        w!(o, "func (s *starter{name}) Close() {{}}");
        for f in &r.methods {
            let mut ps = params_sig(f);
            if f.is_async { ps.insert(0, "ctx context.Context".into()); }
            w!(o, "func (s *starter{name}) {}({}){} {{ panic(\"implement {}.{}\") }}", pascal(&f.name), ps.join(", "), ret_sig(&f.ret), r.name, f.name);
        }
    }
    o
}
